// Railway Infrastructure as Code for the API service (API + web frontend).
// Replaces the deprecated railway.json (Config as Code), which Railway stops
// reading on 2026-12-01. Railway does not read this file on deploy: changes
// reach Railway only through `railway config plan` / `railway config apply`.
// Generated by `railway config migrate --service Social-organizer
// --variables=unmanaged`, plus the gun-data volume and the restart policy
// that railway.json carried.
import { defineRailway, github, project, service, volume } from "railway/iac";

// This file manages only the API service and its volume. PostgreSQL, Redis and
// db-backup stay outside IaC, so a partial keeps apply from touching them.
// See https://docs.railway.com/infrastructure-as-code#multi-repo-projects
export const partial = "Social-organizer";

export default defineRailway(() => {
  // Server-side Gun.js graph copy (apps/api/src/gun-relay.ts).
  const gunData = volume("social-organizer-volume", {
    region: "us-west2",
    sizeMB: 50000,
    allowOnlineResize: true,
    alerts: { usage: { "80": {}, "95": {}, "100": {} } },
  });

  const SocialOrganizer = service("Social-organizer", {
    source: github("element1965/Social-organizer", { branch: "main", checkSuites: false }),
    build: {
      builder: "NIXPACKS",
      buildEnvironment: "V3",
      buildCommand:
        "pnpm install && pnpm db:generate && pnpm build && cp -r apps/web/dist apps/api/dist/public",
    },
    start: "node apps/api/dist/index.js",
    healthcheck: "/health",
    deploy: { restartPolicyType: "ON_FAILURE", restartPolicyMaxRetries: 10 },
    replicas: { "us-west2": 1 },
    domains: [{ domain: "www.orginizer.com", port: 3001 }],
    networking: { privateNetworkEndpoint: "social-organizer" },
    volumeMounts: { "/app/gun-data": gunData },
  });

  return project("Social organizer", {
    // Secrets stay in Railway variables; IaC never reads or writes them.
    variables: { managed: false },
    resources: [SocialOrganizer, gunData],
  });
});
